import{_ as t,o as h,c as o,a3 as a}from"./chunks/framework.DX_KL3e0.js";const i="/help/screenshots/lich-su/tong-quan.png",m=JSON.parse('{"title":"Lịch Sử Hoạt Động","description":"","frontmatter":{},"headers":[],"relativePath":"chuc-nang/lich-su.md","filePath":"chuc-nang/lich-su.md","lastUpdated":1781595364000}'),g={name:"chuc-nang/lich-su.md"};function c(r,n,s,e,l,d){return h(),o("div",null,[...n[0]||(n[0]=[a('<h1 id="lich-su-hoat-đong" tabindex="-1">Lịch Sử Hoạt Động <a class="header-anchor" href="#lich-su-hoat-đong" aria-label="Permalink to &quot;Lịch Sử Hoạt Động&quot;">​</a></h1><p>Module <strong>Lịch Sử Hoạt Động</strong> là nhật ký toàn hệ thống: ghi lại các sự kiện trên tài sản, người dùng và các thao tác quản trị, giúp tra soát và lưu vết.</p><div class="info custom-block"><p class="custom-block-title">Tóm tắt nhanh</p><ul><li><strong>Đường dẫn:</strong> <code>/history</code> (menu <strong>Lịch Sử Hoạt Động</strong>).</li><li><strong>Ai dùng được:</strong> Super Admin, Admin. Vai trò khác cần quyền module <code>history</code>.</li><li><strong>Tính năng:</strong> thống kê nhanh · tìm kiếm · lọc theo hành động · bộ lọc nâng cao · lưu bộ lọc.</li></ul></div><h2 id="giao-dien-chinh" tabindex="-1">Giao diện chính <a class="header-anchor" href="#giao-dien-chinh" aria-label="Permalink to &quot;Giao diện chính&quot;">​</a></h2><p><img src="'+i+'" alt="Trang Lịch sử hoạt động"></p><p>Trang gồm: <strong>thống kê</strong> → <strong>tìm kiếm &amp; bộ lọc</strong> → <strong>danh sách sự kiện</strong>.</p><h3 id="thong-ke-nhanh" tabindex="-1">Thống kê nhanh <a class="header-anchor" href="#thong-ke-nhanh" aria-label="Permalink to &quot;Thống kê nhanh&quot;">​</a></h3><p>Bốn thẻ ở đầu trang: <strong>Tổng sự kiện</strong>, <strong>Xóa tài sản phê duyệt</strong>, <strong>Xóa tài sản từ chối</strong>, <strong>Hoạt động khác</strong>.</p><h3 id="cac-loai-hanh-đong-đuoc-ghi" tabindex="-1">Các loại hành động được ghi <a class="header-anchor" href="#cac-loai-hanh-đong-đuoc-ghi" aria-label="Permalink to &quot;Các loại hành động được ghi&quot;">​</a></h3><p>Mỗi sự kiện có nhãn hành động tô màu, ví dụ:</p><table tabindex="0"><thead><tr><th>Nhóm</th><th>Hành động</th></tr></thead><tbody><tr><td><strong>Tài sản</strong></td><td>Nhập kho · Phân bổ · Bảo trì · Báo hỏng · Thu hồi · Thanh lý · Cập nhật tài sản</td></tr><tr><td><strong>Duyệt xóa</strong></td><td>Xóa tài sản (Phê duyệt) · Xóa tài sản (Từ chối)</td></tr><tr><td><strong>Người dùng</strong></td><td>Tạo người dùng · Cập nhật người dùng · Vô hiệu hóa người dùng</td></tr></tbody></table><p>Mỗi dòng hiển thị: <strong>thời gian</strong>, <strong>nội dung</strong> (mã + tên tài sản hoặc <em>Hành động hệ thống</em>), <strong>hành động</strong>, <strong>người thực hiện</strong> và <strong>ghi chú</strong>.</p><h2 id="tim-kiem-loc" tabindex="-1">Tìm kiếm &amp; lọc <a class="header-anchor" href="#tim-kiem-loc" aria-label="Permalink to &quot;Tìm kiếm &amp; lọc&quot;">​</a></h2><h3 id="tim-kiem-nhanh" tabindex="-1">Tìm kiếm nhanh <a class="header-anchor" href="#tim-kiem-nhanh" aria-label="Permalink to &quot;Tìm kiếm nhanh&quot;">​</a></h3><p>Gõ vào ô tìm kiếm để lọc theo <strong>mã tài sản</strong>, <strong>tên tài sản</strong> hoặc <strong>người thực hiện</strong>.</p><h3 id="loc-theo-hanh-đong" tabindex="-1">Lọc theo hành động <a class="header-anchor" href="#loc-theo-hanh-đong" aria-label="Permalink to &quot;Lọc theo hành động&quot;">​</a></h3><p>Dropdown <strong>Tất cả hành động</strong> liệt kê các loại hành động đang có trong nhật ký để lọc nhanh.</p><h3 id="bo-loc-nang-cao" tabindex="-1">Bộ lọc nâng cao <a class="header-anchor" href="#bo-loc-nang-cao" aria-label="Permalink to &quot;Bộ lọc nâng cao&quot;">​</a></h3><ol><li>Nhấn <strong>Bộ lọc nâng cao</strong> để mở trình tạo điều kiện.</li><li>Chọn trường (Loại thực thể, Hành động, Thực hiện bởi, Thời gian), toán tử (bằng, chứa, bắt đầu/kết thúc bằng…) và giá trị; kết hợp nhiều điều kiện theo AND/OR.</li><li>Áp dụng — số kết quả khớp hiển thị ở chỉ báo phía trên danh sách.</li></ol><div class="tip custom-block"><p class="custom-block-title">Lưu bộ lọc</p><p>Nhấn vào khu vực <strong>Bộ lọc đã lưu</strong> ở góc phải để lưu lại tổ hợp điều kiện hay dùng và nạp lại nhanh ở các lần sau.</p></div><h2 id="cau-hoi-thuong-gap" tabindex="-1">Câu hỏi thường gặp <a class="header-anchor" href="#cau-hoi-thuong-gap" aria-label="Permalink to &quot;Câu hỏi thường gặp&quot;">​</a></h2><p><strong>Nhật ký hiển thị tối đa bao nhiêu sự kiện?</strong> Trang nạp tối đa khoảng 500 sự kiện gần nhất; dùng tìm kiếm/bộ lọc để khoanh vùng dữ liệu cần xem.</p><p><strong>Không thấy menu Lịch Sử?</strong> Module mặc định dành cho Super Admin/Admin. Vai trò khác cần được cấp quyền module <code>history</code>.</p><hr><p><em>Liên quan:</em> <a href="/help/chuc-nang/tai-san.html">Quản lý Tài sản</a> · <a href="/help/chuc-nang/duyet-yeu-cau.html">Duyệt yêu cầu</a> · <a href="/help/quan-tri/nguoi-dung.html">Người dùng</a></p>',25)])])}const p=t(g,[["render",c]]);export{m as __pageData,p as default};
